    U32 initialValue = 0xABCD;
    U32 updatedValue = 0xDCBA;

    Fw::ParamBuffer paramBuff;

    // Serialize initial value
    Fw::SerializeStatus serStat = paramBuff.serializeFrom(initialValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, serStat);

    // Set initial parameter value
    this->invoke_to_setPrm(0, testId, paramBuff);
    this->m_impl.doDispatch();

    // Verify parameter was set by reading it back
    paramBuff.resetSer();
    Fw::ParamValid getStat = this->invoke_to_getPrm(0, testId, paramBuff);
    EXPECT_EQ(Fw::FW_PARAM_OK, getStat);

    U32 readValue;
    serStat = paramBuff.deserializeTo(readValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, serStat);
    EXPECT_EQ(initialValue, readValue);

    // Clear history before update
    this->clearHistory();

    // Serialize updated value
    paramBuff.resetSer();
    serStat = paramBuff.serializeFrom(updatedValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, serStat);

    // Update parameter value
    this->invoke_to_setPrm(0, testId, paramBuff);
    this->m_impl.doDispatch();

    // Verify parameter was updated
    paramBuff.resetSer();
    getStat = this->invoke_to_getPrm(0, testId, paramBuff);
    EXPECT_EQ(Fw::FW_PARAM_OK, getStat);

    readValue = 0;
    serStat = paramBuff.deserializeTo(readValue);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, serStat);
    EXPECT_EQ(updatedValue, readValue);

    // Verify parameter updated event was generated
    ASSERT_EVENTS_PrmIdUpdated_SIZE(1);
    ASSERT_EVENTS_PrmIdUpdated(0, testId);
