void PrmDbTester::testEmptyFileNameRejection() {
    REQUIREMENT("PRMDB-005");

    // Clear any existing history
    this->clearHistory();

    // Pre-populate the staging database with a parameter
    Fw::ParamBuffer pBuff;
    U32 stagedVal = 0x5678;
    FwPrmIdType stagedId = 0x21;

    Fw::SerializeStatus stat = pBuff.serializeFrom(stagedVal);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);
    this->m_impl.updateAddPrmImpl(stagedId, pBuff, PrmDbType::DB_STAGING);
    EXPECT_EQ(this->m_impl.m_stagingDb->getSize(), 1);

    // Verify initial state is IDLE
    EXPECT_EQ(this->m_impl.m_state, PrmDbFileLoadState::IDLE);

    // Send PRM_LOAD_FILE command with empty file name
    this->sendCmd_PRM_LOAD_FILE(0, 10, Fw::String(""), PrmDb_Merge::MERGE);
    this->m_impl.doDispatch();

    // Verify command response is VALIDATION_ERROR
    ASSERT_CMD_RESPONSE_SIZE(1);
    ASSERT_CMD_RESPONSE(0, PrmDbImpl::OPCODE_PRM_LOAD_FILE, 10, Fw::CmdResponse::VALIDATION_ERROR);

    // Verify PrmDbFileLoadFailed event was raised
    ASSERT_EVENTS_SIZE(1);
    ASSERT_EVENTS_PrmDbFileLoadFailed_SIZE(1);

    // Verify no file read errors occurred
    ASSERT_EVENTS_PrmFileReadError_SIZE(0);

    // Verify component state remains IDLE
    EXPECT_EQ(this->m_impl.m_state, PrmDbFileLoadState::IDLE);

    // Verify staging database was not altered
    EXPECT_EQ(this->m_impl.m_stagingDb->getSize(), 1);

    // Verify the parameter in staging database is unchanged
    pBuff.resetSer();
    U32 retrievedVal;
    auto found = this->m_impl.m_stagingDb->find(stagedId, pBuff);
    EXPECT_EQ(found, Fw::Success::SUCCESS);
    stat = pBuff.deserializeTo(retrievedVal);
    EXPECT_EQ(Fw::FW_SERIALIZE_OK, stat);
    EXPECT_EQ(retrievedVal, stagedVal);
}
